with ranked as (select id, dept_id, manager_id, job_title, hire_date, is_remote from employees qualify row_number() over (partition by job_title order by salary, id) = 1) select s.id, s.dept_id, s.manager_id, s.job_title, case when job_title rlike '^(Manager|Director)$' then 'EXTENDED' when job_title rlike '^(Engineer|Analyst)$' then 'GROUP_A' else 'GROUP_B' end as job_title_zone, (select sum(t2.salary) from employees t2 where t2.manager_id = s.manager_id) as sum_employee_salary from ranked s order by manager_id, sum_employee_salary desc;
